import{_ as p,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Signup Form - October CMS User Guide","titleTemplate":false,"description":"Create a signup form where visitors can subscribe to your mailing list.","frontmatter":{"subtitle":"Create a signup form where visitors can subscribe to your mailing list."},"headers":[{"level":2,"title":"Creating the Signup Partial","slug":"creating-the-signup-partial","link":"#creating-the-signup-partial","children":[]},{"level":2,"title":"How the Form Works","slug":"how-the-form-works","link":"#how-the-form-works","children":[]},{"level":2,"title":"Including the Partial","slug":"including-the-partial","link":"#including-the-partial","children":[]},{"level":2,"title":"How Email Confirmation Works","slug":"how-email-confirmation-works","link":"#how-email-confirmation-works","children":[]},{"level":2,"title":"Creating Confirmation and Unsubscribe Pages","slug":"creating-confirmation-and-unsubscribe-pages","link":"#creating-confirmation-and-unsubscribe-pages","children":[]},{"level":2,"title":"Try It Out","slug":"try-it-out","link":"#try-it-out","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/mailing-list/signup-form.md","filePath":"user-guide/mailing-list/signup-form.md"}'),i={name:"user-guide/mailing-list/signup-form.md"};function r(k,a,g,d,m,h){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Signup Form",-1)),s(e),a[1]||(a[1]=u(`<p>Now that you have a subscriber list and campaign template, you need a way for visitors to join your mailing list. In this step, you will build a signup form as a CMS partial so it can be included anywhere on your site.</p><h2 id="creating-the-signup-partial"><a href="#creating-the-signup-partial" class="header-anchor">#</a> Creating the Signup Partial</h2><p>Create a new partial at <code>partials/subscribe-form.htm</code>:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">campaignSignup</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">list</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">newsletter</span>&quot;</span>
<span class="token key attr-name">confirm</span> <span class="token punctuation">=</span> <span class="token value attr-value">1</span>
<span class="token key attr-name">templatePage</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">campaign/default-template</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>subscribe-form<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-lg font-semibold mb-3<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Subscribe to our newsletter
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>campaignSignup::onSignup<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ subscribe_result: &#39;#subscribe-form&#39; }<span class="token punctuation">&quot;</span></span>
    <span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex flex-col sm:flex-row gap-2 mb-2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
                <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>first_name<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>First name<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>px-3 py-2 border border-gray-300 rounded-md text-sm<span class="token punctuation">&quot;</span></span>
            <span class="token punctuation">/&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
                <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>last_name<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Last name<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>px-3 py-2 border border-gray-300 rounded-md text-sm<span class="token punctuation">&quot;</span></span>
            <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex gap-2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
                <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>you@example.com<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-1 px-3 py-2 border border-gray-300 rounded-md text-sm<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">required</span>
            <span class="token punctuation">/&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-attach-loading</span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>px-4 py-2 bg-blue-600 text-white text-sm rounded-md hover:bg-blue-700<span class="token punctuation">&quot;</span></span>
            <span class="token punctuation">&gt;</span></span>
                Subscribe
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-xs text-gray-500 mt-2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            We will never spam or share your email address.
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The result partial is rendered after the form is submitted. Create a new partial at <code>partials/subscribe_result.htm</code>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> error <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>p-3 bg-red-50 text-red-700 text-sm rounded-md<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> error <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> isThrottled <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>p-3 bg-yellow-50 text-yellow-700 text-sm rounded-md<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Please wait a few minutes before making another subscription request.
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> requireConfirmation <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>p-3 bg-green-50 text-green-700 text-sm rounded-md<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        We have sent you an email to confirm your subscription. Please check your inbox.
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>p-3 bg-green-50 text-green-700 text-sm rounded-md<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        You are now subscribed. Welcome aboard!
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="how-the-form-works"><a href="#how-the-form-works" class="header-anchor">#</a> How the Form Works</h2><p>The form uses <code>data-request=&quot;campaignSignup::onSignup&quot;</code> to call the signup handler. The <code>campaignSignup::</code> prefix is the component alias, which is needed because the partial can be included on any page.</p><p>The <code>data-request-update</code> attribute tells the AJAX framework to replace the <code>#subscribe-form</code> container with the <code>subscribe_result</code> partial after the handler completes. This gives the visitor immediate feedback without a full page reload.</p><p>The component properties control the behavior:</p><ul><li><code>list = &quot;newsletter&quot;</code>: the subscriber is added to the &quot;Newsletter&quot; list you created earlier</li><li><code>confirm = 1</code>: the subscriber must confirm their email address before they are fully added</li><li><code>templatePage = &quot;campaign/default-template&quot;</code>: the CMS page used to generate the email confirmation URL</li></ul><h2 id="including-the-partial"><a href="#including-the-partial" class="header-anchor">#</a> Including the Partial</h2><p>Add the signup form to any page or layout using the <code>partial</code> tag. For example, to add it to the footer of your default layout:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>footer</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bg-gray-100 border-t border-gray-200 mt-12<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>max-w-5xl mx-auto px-4 py-8<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>subscribe-form<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>footer</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You can also create a dedicated subscribe page. Create a page at <code>pages/subscribe.htm</code>:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Subscribe</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/subscribe</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>max-w-md mx-auto<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>subscribe-form<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="how-email-confirmation-works"><a href="#how-email-confirmation-works" class="header-anchor">#</a> How Email Confirmation Works</h2><p>With <code>confirm = 1</code>, the signup process works in two steps:</p><ol><li>The visitor fills in the form and submits it. The plugin creates a subscriber record (marked as unconfirmed) and sends a verification email.</li><li>The subscriber clicks the confirmation link in the email. The link points to your campaign template page (<code>campaign/default-template.htm</code>) with a <code>?verify=1</code> parameter. The <code>campaignTemplate</code> component verifies the subscriber and redirects them to a confirmation page.</li></ol><p>The verification email is sent using the <code>responsiv.campaign::mail.confirm_subscriber</code> mail template, which you can customize under <strong>Settings &gt; Mail Templates</strong>.</p><h2 id="creating-confirmation-and-unsubscribe-pages"><a href="#creating-confirmation-and-unsubscribe-pages" class="header-anchor">#</a> Creating Confirmation and Unsubscribe Pages</h2><p>When subscribers confirm their email or unsubscribe from a campaign, they should land on a friendly page rather than a plain HTML message. Create two simple pages for this.</p><p>Create a page at <code>pages/subscribe/confirmed.htm</code>:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Subscription Confirmed</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/subscribe/confirmed</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>max-w-md mx-auto text-center py-12<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-2xl font-bold mb-4<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        You are confirmed!
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-gray-600 mb-6<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Your email address has been verified and you are now subscribed to our newsletter.
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/<span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-blue-600 hover:underline<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Return to the homepage
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Create a page at <code>pages/subscribe/goodbye.htm</code>:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Unsubscribed</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/subscribe/goodbye</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>max-w-md mx-auto text-center py-12<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-2xl font-bold mb-4<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        You have been unsubscribed
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-gray-600 mb-6<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        You will no longer receive emails from us. If this was a mistake, you can subscribe again at any time.
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/<span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-blue-600 hover:underline<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Return to the homepage
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Now update the <code>campaignTemplate</code> component in <code>campaign/default-template.htm</code> to redirect to these pages. Open the page in the CMS Editor and update the component configuration:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">campaignTemplate</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">verifyPage</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">subscribe/confirmed</span>&quot;</span>
<span class="token key attr-name">unsubscribePage</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">subscribe/goodbye</span>&quot;</span>
</code></pre></div><p>When a subscriber confirms their email, they are redirected to <code>/subscribe/confirmed</code>. When they click an unsubscribe link in a campaign email, they are redirected to <code>/subscribe/goodbye</code>.</p><h2 id="try-it-out"><a href="#try-it-out" class="header-anchor">#</a> Try It Out</h2><ol><li>Include the signup partial on a page and visit it in your browser</li><li>Fill in the form with your email address and submit it</li><li>Check <strong>Mailing List &gt; Subscribers</strong> in the backend to see the new subscriber (marked as unconfirmed)</li><li>Check your email inbox for the confirmation message and click the verification link</li><li>You should be redirected to the &quot;Subscription Confirmed&quot; page</li><li>Back in the backend, verify the subscriber is now confirmed</li></ol><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Continue to <a href="./sending-campaigns.html">Sending Campaigns</a> to compose and send your first email campaign.</p>`,33))])}const q=p(i,[["render",r]]);export{v as __pageData,q as default};
